using System.Linq;
using FishNet.Managing;
using FishNet.Managing.Object;
using FishNet.Object;
using FishNet.Transporting.Tugboat;
using Game.Gameplay;
using Game.Net;
using UnityEditor;
using UnityEngine;
using static EditorFields;

// Adds a host-run match (network manager, match director, spawn points, HUD) to the scene being built.
// Uses the combatant and loot prefabs generated by TestBoxBuilder.
public static class MatchKit
{
    public struct Spawn
    {
        public Vector3 Position;
        public float Yaw;
    }

    public static Spawn At(float x, float y, float z, float yaw = 0f) => new Spawn { Position = new Vector3(x, y, z), Yaw = yaw };

    // `bots`: where bots start (needs the Bot prefab from TestBoxBuilder). Null or empty = no bots, the scene is as before.
    public static MatchDirector AddMatch(Spawn[] players, Spawn[] loot, Spawn[] dummies, Spawn[] bots = null)
    {
        var go = new GameObject("Match");
        var nm = go.AddComponent<NetworkManager>();
        // The manager lives and dies with the match scene so a restart gets a fresh one.
        Set(nm, "_dontDestroyOnLoad", p => p.boolValue = false);
        nm.SpawnablePrefabs = AssetDatabase.LoadAssetAtPath<DefaultPrefabObjects>("Assets/DefaultPrefabObjects.asset");
        EditorUtility.SetDirty(nm);
        go.AddComponent<Tugboat>();
        var director = go.AddComponent<MatchDirector>();
        // The region lockdown (M3); its barriers, banner and fog install themselves when it starts.
        go.AddComponent<ZoneDirector>();

        Set(director, "_networkManager", p => p.objectReferenceValue = nm);
        Set(director, "_playerPrefab", p => p.objectReferenceValue = Prefab("Player"));
        var playerVariants = CharacterRoster.Entries.Select(e => AssetDatabase.LoadAssetAtPath<NetworkObject>($"{TestBoxBuilder.PrefabDir}/Player_{e.Id}.prefab")).Where(v => v != null).ToArray();
        if (playerVariants.Length > 0) SetArray(director, "_playerVariants", playerVariants);
        Set(director, "_lootPrefab", p => p.objectReferenceValue = Prefab("LootItem"));
        Set(director, "_dummyPrefab", p => p.objectReferenceValue = Prefab("TrainingDummy"));
        SetArray(director, "_playerSpawns", Points(go.transform, "PlayerSpawn", players));
        SetArray(director, "_lootSpawns", Points(go.transform, "LootSpawn", loot));
        SetArray(director, "_dummySpawns", Points(go.transform, "DummySpawn", dummies));
        if (bots != null && bots.Length > 0)
        {
            Set(director, "_botPrefab", p => p.objectReferenceValue = Prefab("Bot"));
            // One bot prefab per roster model (TestBoxBuilder.BuildBotVariants): the match mixes all of them.
            var variants = CharacterRoster.Entries.Select(e => AssetDatabase.LoadAssetAtPath<NetworkObject>($"{TestBoxBuilder.PrefabDir}/Bot_{e.Id}.prefab")).Where(v => v != null).ToArray();
            if (variants.Length > 0) SetArray(director, "_botVariants", variants);
            SetArray(director, "_botSpawns", Points(go.transform, "BotSpawn", bots));
        }

        new GameObject("HUD").AddComponent<Hud>();
        return director;
    }

    static NetworkObject Prefab(string name)
    {
        var path = $"{TestBoxBuilder.PrefabDir}/{name}.prefab";
        var prefab = AssetDatabase.LoadAssetAtPath<NetworkObject>(path);
        if (prefab == null) throw new System.IO.FileNotFoundException("prefab missing (run TestBoxBuilder.Build first): " + path);
        return prefab;
    }

    static Transform[] Points(Transform parent, string prefix, Spawn[] spawns)
    {
        var points = new Transform[spawns.Length];
        for (int i = 0; i < spawns.Length; i++)
        {
            var t = new GameObject(prefix + i).transform;
            t.SetParent(parent, false);
            t.SetPositionAndRotation(spawns[i].Position, Quaternion.Euler(0, spawns[i].Yaw, 0));
            points[i] = t;
        }
        return points;
    }
}
